From e955bfba296cbe2178e1f123254dffae8134da30 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 21:20:53 +0100
Subject: [PATCH] desktoppackage: Offer Auto hide in Tablet Mode for panels

The panel settings only listed visibility modes that apply all the time.
Add the Auto hide in Tablet Mode entry to the Visibility combobox, and
make the panel float and dodge following the mode it is acting as now.

BUG: 517517
---
 .../contents/configuration/PanelConfiguration.qml      | 10 ++++++++--
 desktoppackage/contents/views/Panel.qml                |  4 ++--
 2 files changed, 10 insertions(+), 4 deletions(-)

diff --git a/desktoppackage/contents/configuration/PanelConfiguration.qml b/desktoppackage/contents/configuration/PanelConfiguration.qml
index cb897a1f04..a0bd83a22b 100644
--- a/desktoppackage/contents/configuration/PanelConfiguration.qml
+++ b/desktoppackage/contents/configuration/PanelConfiguration.qml
@@ -379,7 +379,7 @@ ColumnLayout {
             PanelRepresentation {
                 id: visibilityRepresentation
                 Layout.alignment: Qt.AlignHCenter
-                sunkenPanel: autoHideBox.previewIndex == 1 || autoHideBox.previewIndex == 2
+                sunkenPanel: autoHideBox.previewIndex == 1 || autoHideBox.previewIndex == 2 || autoHideBox.previewIndex == 4
                 onClicked: autoHideBox.popup.visible = true
                 windowVisible: true
                 panelReservesSpace: autoHideBox.previewIndex == 0
@@ -394,11 +394,12 @@ ColumnLayout {
                     i18ndc("plasma_shell_org.kde.plasma.desktop", "@item:inlistbox", "Auto hide"),
                     i18ndc("plasma_shell_org.kde.plasma.desktop", "@item:inlistbox", "Dodge windows"),
                     i18ndc("plasma_shell_org.kde.plasma.desktop", "@item:inlistbox", "Windows go below"),
+                    i18ndc("plasma_shell_org.kde.plasma.desktop", "@item:inlistbox", "Auto hide in Tablet Mode"),
                 ]
                 onPreviewIndexChanged: {
                     if (previewIndex == 0 || previewIndex == 3) {
                         visibilityRepresentation.maximizeWindow()
-                    } else if (previewIndex == 1) {
+                    } else if (previewIndex == 1 || previewIndex == 4) {
                         visibilityRepresentation.hidePanel()
                     } else if (previewIndex == 2) {
                         visibilityRepresentation.dodgePanel()
@@ -414,6 +415,8 @@ ColumnLayout {
                             return 2;
                         case Panel.WindowsGoBelow:
                             return 3;
+                        case Panel.AutoHideInTabletMode:
+                            return 4;
                         case Panel.NormalPanel:
                         default:
                             return 0;
@@ -430,6 +433,9 @@ ColumnLayout {
                         case 3:
                             panel.visibilityMode = Panel.WindowsGoBelow;
                             break;
+                        case 4:
+                            panel.visibilityMode = Panel.AutoHideInTabletMode;
+                            break;
                         case 0:
                         default:
                             panel.visibilityMode = Panel.NormalPanel;
diff --git a/desktoppackage/contents/views/Panel.qml b/desktoppackage/contents/views/Panel.qml
index aea1844c5b..35bc5ffac3 100644
--- a/desktoppackage/contents/views/Panel.qml
+++ b/desktoppackage/contents/views/Panel.qml
@@ -118,7 +118,7 @@ Item {

         Binding on regionGeometry {
             delayed: true
-            value: panel.width, panel.height, panel.x, panel.y, panel.dogdeGeometryByDistance(panel.visibilityMode === Panel.DodgeWindows ? -1 : 1) // +1 is for overlap detection, -1 is for snapping to panel
+            value: panel.width, panel.height, panel.x, panel.y, panel.dogdeGeometryByDistance(panel.effectiveVisibilityMode === Panel.DodgeWindows ? -1 : 1) // +1 is for overlap detection, -1 is for snapping to panel
         }
     }

@@ -215,7 +215,7 @@ Item {
         // Exceptions: panels with not NormalPanel visibilityMode
         // should never de-float, and we should not have transparent
         // panels when on X11 with compositing not active.
-        if (panel.visibilityMode != Panel.NormalPanel && floating) {
+        if (panel.effectiveVisibilityMode != Panel.NormalPanel && floating) {
             floatingnessTarget = 1
             floatingApplets = true
         }
-- 
2.53.0

From 6e7ba27c64e7664e4644668ed3d4c80c64e8f2be Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 21:20:52 +0100
Subject: [PATCH] shell/panelview: Add an Auto hide in Tablet Mode visibility
 mode

Panels could only auto hide all the time, so tablet users had to choose
between a panel in the way and one that also hides on the desktop. The
new mode auto hides in Tablet Mode and is always visible otherwise.

BUG: 517517
---
 CMakeLists.txt                 |  2 +-
 shell/CMakeLists.txt           |  1 +
 shell/autotests/CMakeLists.txt |  1 +
 shell/panelview.cpp            | 41 ++++++++++++++++++++++++++--------
 shell/panelview.h              |  9 ++++++++
 shell/scripting/panel.cpp      |  5 +++++
 shell/shellcorona.cpp          | 15 ++++++++-----
 7 files changed, 58 insertions(+), 16 deletions(-)

diff --git a/CMakeLists.txt b/CMakeLists.txt
index f93dda5aa7..0240238a28 100644
--- a/CMakeLists.txt
+++ b/CMakeLists.txt
@@ -70,7 +70,7 @@ find_package(KF6 ${KF6_MIN_VERSION} REQUIRED COMPONENTS
                     Archive Auth CoreAddons Crash DBusAddons Declarative GlobalAccel GuiAddons
                     Holidays I18n IconThemes IdleTime ItemModels KCMUtils KDED KIO NewStuff
                     Notifications Package Parts Prison Runner StatusNotifierItem
-                    Svg TextEditor TextWidgets Wallet ColorScheme
+                    Svg TextEditor TextWidgets Wallet ColorScheme KirigamiPlatform
                     OPTIONAL_COMPONENTS DocTools)
 find_package(Plasma ${PROJECT_DEP_VERSION} REQUIRED)
 find_package(PlasmaQuick ${PROJECT_DEP_VERSION} REQUIRED)
diff --git a/shell/CMakeLists.txt b/shell/CMakeLists.txt
index 05393e8838..325e80d45a 100644
--- a/shell/CMakeLists.txt
+++ b/shell/CMakeLists.txt
@@ -117,6 +117,7 @@ target_link_libraries(plasmashell PRIVATE
  KF6::GuiAddons
  KF6::I18n
  KF6::I18nQml
+ KF6::KirigamiPlatform
  KF6::KIOCore
  KF6::Package
  KF6::Notifications
diff --git a/shell/autotests/CMakeLists.txt b/shell/autotests/CMakeLists.txt
index 368cbd4542..bd947b6473 100644
--- a/shell/autotests/CMakeLists.txt
+++ b/shell/autotests/CMakeLists.txt
@@ -53,6 +53,7 @@ MACRO(PLASMASHELL_UNIT_TESTS)
                             KF6::XmlGui
                             KF6::I18n
                             KF6::I18nQml
+                            KF6::KirigamiPlatform
                             KF6::GlobalAccel
                             Qt::Quick
                             Qt::DBus
diff --git a/shell/panelview.cpp b/shell/panelview.cpp
index 5c0ac43e71..f3a31737fd 100644
--- a/shell/panelview.cpp
+++ b/shell/panelview.cpp
@@ -31,6 +31,8 @@

 #include <KLocalizedString>

+#include <Kirigami/Platform/TabletModeWatcher>
+
 #include <Plasma/Containment>
 #include <PlasmaQuick/AppletQuickItem>

@@ -89,6 +91,11 @@ PanelView::PanelView(ShellCorona *corona, QScreen *targetScreen, QWindow *parent
     connect(&m_unhideTimer, &QTimer::timeout, this, &PanelView::restoreAutoHide);

     connect(m_corona, &Plasma::Corona::editModeChanged, this, &PanelView::restoreAutoHide);
+    connect(Kirigami::Platform::TabletModeWatcher::self(), &Kirigami::Platform::TabletModeWatcher::tabletModeChanged, this, [this] {
+        if (m_visibilityMode == AutoHideInTabletMode && containment()) {
+            applyVisibilityMode();
+        }
+    });

     m_lastScreen = targetScreen;
     connect(this, &PanelView::containmentChanged, this, &PanelView::refreshContainment);
@@ -459,20 +466,27 @@ void PanelView::setVisibilityMode(PanelView::VisibilityMode mode)

     m_visibilityMode = mode;

-    disconnect(containment(), &Plasma::Applet::activated, this, &PanelView::showTemporarily);
-    if (edgeActivated()) {
-        connect(containment(), &Plasma::Applet::activated, this, &PanelView::showTemporarily);
-    }
-
     if (hasConfig()) {
         // panelVisibility is not resolution dependent, don't write to Defaults
         resolutionIndependentConfig().writeEntry("panelVisibility", (int)mode);
         m_corona->requestApplicationConfigSync();
     }

+    Q_EMIT visibilityModeChanged();
+
+    applyVisibilityMode();
+}
+
+void PanelView::applyVisibilityMode()
+{
+    disconnect(containment(), &Plasma::Applet::activated, this, &PanelView::showTemporarily);
+    if (edgeActivated()) {
+        connect(containment(), &Plasma::Applet::activated, this, &PanelView::showTemporarily);
+    }
+
     updateExclusiveZone();

-    Q_EMIT visibilityModeChanged();
+    Q_EMIT effectiveVisibilityModeChanged();

     restoreAutoHide();
 }
@@ -482,6 +496,14 @@ PanelView::VisibilityMode PanelView::visibilityMode() const
     return m_visibilityMode;
 }

+PanelView::VisibilityMode PanelView::effectiveVisibilityMode() const
+{
+    if (m_visibilityMode == AutoHideInTabletMode) {
+        return Kirigami::Platform::TabletModeWatcher::self()->isTabletMode() ? AutoHide : NormalPanel;
+    }
+    return m_visibilityMode;
+}
+
 PanelView::OpacityMode PanelView::opacityMode() const
 {
     if (!m_theme.adaptiveTransparencyEnabled()) {
@@ -981,7 +1003,7 @@ void PanelView::restoreAutoHide()

 void PanelView::setAutoHideEnabled(bool enabled)
 {
-    if (m_visibilityMode == VisibilityMode::AutoHide || (m_visibilityMode == VisibilityMode::DodgeWindows && m_touchingWindow)) {
+    if (effectiveVisibilityMode() == VisibilityMode::AutoHide || (effectiveVisibilityMode() == VisibilityMode::DodgeWindows && m_touchingWindow)) {
         if (!m_autoHideScreenEdge) {
             m_autoHideScreenEdge = AutoHideScreenEdge::create(this);
         }
@@ -1463,7 +1485,7 @@ void PanelView::updateExclusiveZone()
         return;
     }

-    switch (m_visibilityMode) {
+    switch (effectiveVisibilityMode()) {
     case NormalPanel:
         if (m_corona->shouldPanelReserveSpace(this)) {
             m_layerWindow->setExclusiveZone(thickness());
@@ -1472,6 +1494,7 @@ void PanelView::updateExclusiveZone()
         }
         break;
     case AutoHide:
+    case AutoHideInTabletMode:
     case DodgeWindows:
     case WindowsGoBelow:
         m_layerWindow->setExclusiveZone(-1);
@@ -1654,7 +1677,7 @@ void PanelView::screenDestroyed(QObject *)

 bool PanelView::edgeActivated() const
 {
-    return m_visibilityMode == PanelView::AutoHide || m_visibilityMode == PanelView::DodgeWindows;
+    return effectiveVisibilityMode() == PanelView::AutoHide || effectiveVisibilityMode() == PanelView::DodgeWindows;
 }

 void PanelView::updateEnabledBorders()
diff --git a/shell/panelview.h b/shell/panelview.h
index eb276bf7f6..75b367b034 100644
--- a/shell/panelview.h
+++ b/shell/panelview.h
@@ -92,6 +92,11 @@ class PanelView : public PlasmaQuick::ContainmentView
      */
     Q_PROPERTY(VisibilityMode visibilityMode READ visibilityMode WRITE setVisibilityMode NOTIFY visibilityModeChanged)

+    /**
+     *  the visibility mode the panel currently behaves as: AutoHideInTabletMode becomes AutoHide or NormalPanel
+     */
+    Q_PROPERTY(VisibilityMode effectiveVisibilityMode READ effectiveVisibilityMode NOTIFY effectiveVisibilityModeChanged)
+
     /**
      *  Property that determines how a panel's opacity behaves.
      *
@@ -148,6 +153,7 @@ public:
         AutoHide, /**the panel will be shownn only if the mouse cursor is on screen edges */
         DodgeWindows, /* the panel will be normally visible, but will hide if a window would cover it */
         WindowsGoBelow, /* the panel is always visible but will not reserve any space */
+        AutoHideInTabletMode, /* the panel behaves like AutoHide in Tablet Mode and like NormalPanel otherwise */
     };
     Q_ENUM(VisibilityMode)

@@ -211,6 +217,7 @@ public:

     VisibilityMode visibilityMode() const;
     void setVisibilityMode(PanelView::VisibilityMode mode);
+    VisibilityMode effectiveVisibilityMode() const;

     PanelView::OpacityMode opacityMode() const;
     bool adaptiveOpacityEnabled();
@@ -281,6 +288,7 @@ Q_SIGNALS:
     // QWindow does not have a property for screen. Adding this property requires re-implementing the signal
     void screenToFollowChanged(QScreen *screen);
     void visibilityModeChanged();
+    void effectiveVisibilityModeChanged();
     void opacityModeChanged();
     void lengthModeChanged();
     void adaptiveOpacityEnabledChanged();
@@ -293,6 +301,7 @@ protected Q_SLOTS:
     void showConfigurationInterface(Plasma::Applet *applet) override;

 private Q_SLOTS:
+    void applyVisibilityMode();
     void setAutoHideEnabled(bool autoHideEnabled);
     void showTemporarily();
     void refreshContainment();
diff --git a/shell/scripting/panel.cpp b/shell/scripting/panel.cpp
index b60a3f4275..7b3789807f 100644
--- a/shell/scripting/panel.cpp
+++ b/shell/scripting/panel.cpp
@@ -314,6 +314,8 @@ QString Panel::hiding() const
         return u"autohide"_s;
     case PanelView::DodgeWindows:
         return u"dodgewindows"_s;
+    case PanelView::AutoHideInTabletMode:
+        return u"autohideintabletmode"_s;
     }
     return u"none"_s;
 }
@@ -330,6 +332,9 @@ void Panel::setHiding(const QString &mode)
     if (mode.compare(u"windowsgobelow", Qt::CaseInsensitive) == 0) {
         visibilityMode = PanelView::WindowsGoBelow;
     }
+    if (mode.compare(u"autohideintabletmode", Qt::CaseInsensitive) == 0) {
+        visibilityMode = PanelView::AutoHideInTabletMode;
+    }

     if (panel()) {
         panel()->setVisibilityMode(visibilityMode);
diff --git a/shell/shellcorona.cpp b/shell/shellcorona.cpp
index 51bde18ac6..e93fd869a3 100644
--- a/shell/shellcorona.cpp
+++ b/shell/shellcorona.cpp
@@ -508,6 +508,9 @@ QByteArray ShellCorona::dumpCurrentLayoutJS() const
             case PanelView::AutoHide:
                 panelJson.insert(u"hiding", u"autohide"_s);
                 break;
+            case PanelView::AutoHideInTabletMode:
+                panelJson.insert(u"hiding", u"autohideintabletmode"_s);
+                break;
             case PanelView::DodgeWindows:
                 panelJson.insert(u"hiding", u"dodgewindows"_s);
                 break;
@@ -1217,7 +1220,7 @@ QRegion ShellCorona::_availableScreenRegion(uint id) const
     }

     return std::accumulate(m_panelViews.cbegin(), m_panelViews.cend(), QRegion(screen->geometry()), [screen](const QRegion &a, const PanelView *v) {
-        if (v->isVisible() && screen == v->screen() && v->visibilityMode() != PanelView::AutoHide) {
+        if (v->isVisible() && screen == v->screen() && v->effectiveVisibilityMode() != PanelView::AutoHide) {
             // if the panel is being moved around, we still want to calculate it from the edge
             return a - v->geometryByDistance(0);
         }
@@ -1231,7 +1234,7 @@ QRect ShellCorona::strictAvailableScreenRect(uint id) const

     // Remove previously ignored autohide panels
     for (PanelView *v : m_panelViews) {
-        if (v->visibilityMode() == PanelView::AutoHide) {
+        if (v->effectiveVisibilityMode() == PanelView::AutoHide) {
             switch (v->location()) {
             case Plasma::Types::LeftEdge:
                 rect.setLeft(rect.left() + v->totalThickness());
@@ -1285,7 +1288,7 @@ QRect ShellCorona::_availableScreenRect(uint id) const
     int topThickness, leftThickness, rightThickness, bottomThickness;
     topThickness = leftThickness = rightThickness = bottomThickness = 0;
     for (PanelView *v : m_panelViews) {
-        if (v->isVisible() && v->screen() == screen && v->visibilityMode() != PanelView::AutoHide) {
+        if (v->isVisible() && v->screen() == screen && v->effectiveVisibilityMode() != PanelView::AutoHide) {
             switch (v->location()) {
             case Plasma::Types::LeftEdge:
                 leftThickness = accumulator(leftThickness, v->totalThickness());
@@ -1628,7 +1631,7 @@ void ShellCorona::createWaitingPanels()
         connect(panel, &QWindow::visibleChanged, this, rectNotify);
         connect(panel, &QWindow::screenChanged, this, rectNotify);
         connect(panel, &PanelView::locationChanged, this, rectNotify);
-        connect(panel, &PanelView::visibilityModeChanged, this, rectNotify);
+        connect(panel, &PanelView::effectiveVisibilityModeChanged, this, rectNotify);
         connect(panel, &PanelView::thicknessChanged, this, rectNotify);
         connect(panel, &PanelView::userConfiguringChanged, this, &ShellCorona::panelBeingConfiguredChanged);

@@ -2547,8 +2550,8 @@ bool ShellCorona::shouldPanelReserveSpace(PanelView *panel)
 {
     PanelView *thickestVisiblePanel = nullptr;
     for (auto it = m_panelViews.constBegin(); it != m_panelViews.constEnd(); ++it) {
-        if ((*it)->screenToFollow() == panel->screenToFollow() && (*it)->location() == panel->location() && (*it)->visibilityMode() == PanelView::NormalPanel
-            && (*it)) {
+        if ((*it)->screenToFollow() == panel->screenToFollow() && (*it)->location() == panel->location()
+            && (*it)->effectiveVisibilityMode() == PanelView::NormalPanel && (*it)) {
             if ((thickestVisiblePanel && (*it)->thickness() > thickestVisiblePanel->thickness()) || !thickestVisiblePanel) {
                 thickestVisiblePanel = (*it);
             }
-- 
2.53.0
